#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 1;
    std::istringstream reader(line);
    long long total = 0;
    int count = 0;
    std::string token;
    while (reader >> token) {
        if (count >= 100) return 1;
        long long value = 0;
        try {
            std::size_t pos = 0;
            value = std::stoll(token, &pos);
            if (pos != token.size()) return 1;
        } catch (...) {
            return 1;
        }
        if (value < -10000 || value > 10000) return 1;
        total += value;
        count++;
    }
    std::cout << total << std::endl;
    return 0;
}
